function looksLikeEmail(value) {
  const text = String(value || '').trim();
  const at = text.indexOf('@');
  if (at <= 0 || at !== text.lastIndexOf('@')) return false;
  const local = text.slice(0, at);
  const domain = text.slice(at + 1);
  if (!/^[A-Za-z0-9._%+\-]+$/.test(local)) return false;
  if (!/^[A-Za-z0-9.\-]+\.[A-Za-z]{2,}$/.test(domain)) return false;
  return true;
}

function validateLead(body) {
  const source = body && typeof body === 'object' ? body : {};
  const errors = [];
  const name = String(source.name || '').trim();
  const email = String(source.email || '').trim().toLowerCase();
  const company = String(source.company || '').trim();
  const message = String(source.message || '').trim();
  const origin = String(source.source || 'webhook').trim() || 'webhook';
  if (name.length < 2) errors.push('name must be at least 2 characters');
  if (!looksLikeEmail(email)) errors.push('email format is invalid');
  if (!company) errors.push('company is required');
  if (message.length < 5) errors.push('message must be at least 5 characters');
  return {
    ok: errors.length === 0,
    errors: errors,
    lead: { name: name, email: email, company: company, message: message, source: origin },
  };
}

if (typeof $input === 'undefined') {
  return { validateLead: validateLead, looksLikeEmail: looksLikeEmail };
}

const item = $input.first().json || {};
const body = item.body && typeof item.body === 'object' ? item.body : item;
const check = validateLead(body);
return [{
  json: {
    valid: check.ok ? 'yes' : 'no',
    errors: check.errors,
    lead: check.lead,
    httpStatus: check.ok ? 200 : 400,
  },
}];

function validationLog(item) {
  return {
    valid: 'no',
    duplicate: 'no',
    accepted: 'no',
    errors: item && item.errors ? item.errors : [],
    httpStatus: 400,
    branch: 'validation',
  };
}

if (typeof $input === 'undefined') {
  return { validationLog: validationLog };
}

const item = $input.first().json || {};
const entry = validationLog(item);
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.logs)) staticData.logs = [];
staticData.logs.push({ at: new Date().toISOString(), branch: 'validation', errors: entry.errors });
if (staticData.logs.length > 50) staticData.logs = staticData.logs.slice(-50);
return [{ json: entry }];

function dedupeDecision(seen, email, utcDay) {
  const key = String(email || '').toLowerCase() + '|' + String(utcDay || '');
  const map = seen && typeof seen === 'object' ? seen : {};
  return {
    key: key,
    duplicate: Object.prototype.hasOwnProperty.call(map, key),
  };
}

if (typeof $input === 'undefined') {
  return { dedupeDecision: dedupeDecision };
}

const lead = $input.first().json.lead || {};
const staticData = $getWorkflowStaticData('global');
if (!staticData.seen || typeof staticData.seen !== 'object') staticData.seen = {};
const day = new Date().toISOString().slice(0, 10);
const decision = dedupeDecision(staticData.seen, lead.email, day);
if (!decision.duplicate) staticData.seen[decision.key] = day;
return [{
  json: {
    name: lead.name,
    email: lead.email,
    company: lead.company,
    message: lead.message,
    source: lead.source,
    duplicate: decision.duplicate ? 'yes' : 'no',
    dedupeKey: decision.key,
  },
}];

function duplicateLog(item) {
  return {
    valid: 'yes',
    duplicate: 'yes',
    accepted: 'no',
    name: item && item.name ? item.name : '',
    company: item && item.company ? item.company : '',
    httpStatus: 200,
    branch: 'duplicate',
  };
}

if (typeof $input === 'undefined') {
  return { duplicateLog: duplicateLog };
}

const item = $input.first().json || {};
const entry = duplicateLog(item);
const staticData = $getWorkflowStaticData('global');
if (!Array.isArray(staticData.logs)) staticData.logs = [];
staticData.logs.push({ at: new Date().toISOString(), branch: 'duplicate', dedupeKey: item.dedupeKey || '' });
if (staticData.logs.length > 50) staticData.logs = staticData.logs.slice(-50);
return [{ json: entry }];

function scoreLead(lead) {
  const message = String((lead && lead.message) || '');
  const company = String((lead && lead.company) || '');
  let score = 10;
  const reasons = ['base +10'];
  if (company.trim().length >= 2) {
    score += 10;
    reasons.push('company present +10');
  }
  const rules = [
    ['budget', 20],
    ['timeline', 15],
    ['demo', 10],
    ['pricing', 10],
    ['integration', 8],
  ];
  const lower = message.toLowerCase();
  for (let i = 0; i < rules.length; i++) {
    const word = rules[i][0];
    const points = rules[i][1];
    if (lower.indexOf(word) !== -1) {
      score += points;
      reasons.push(word + ' +' + points);
    }
  }
  if (/\b(support|refund|outage|bug|broken)\b/i.test(message) && score > 39) {
    score = 39;
    reasons.push('support wording caps the score at 39');
  }
  if (score > 100) {
    score = 100;
    reasons.push('capped at 100');
  }
  if (score < 0) score = 0;
  let band = 'cold';
  if (score >= 70) band = 'hot';
  else if (score >= 40) band = 'warm';
  reasons.push('total ' + score);
  return { score: score, band: band, reasons: reasons };
}

if (typeof $input === 'undefined') {
  return { scoreLead: scoreLead };
}

const lead = $input.first().json;
const scored = scoreLead(lead);
return [{
  json: {
    name: lead.name,
    email: lead.email,
    company: lead.company,
    message: lead.message,
    source: lead.source,
    score: scored.score,
    band: scored.band,
    reasonsText: scored.reasons.join('; '),
  },
}];

function acceptedReply(lead) {
  return {
    accepted: 'yes',
    valid: 'yes',
    duplicate: 'no',
    name: lead && lead.name ? lead.name : '',
    company: lead && lead.company ? lead.company : '',
    score: lead && typeof lead.score === 'number' ? lead.score : null,
    band: lead && lead.band ? lead.band : '',
    httpStatus: 200,
  };
}

if (typeof $input === 'undefined') {
  return { acceptedReply: acceptedReply };
}

const lead = $('Score Lead').first().json;
return [{ json: acceptedReply(lead) }];

function appendLog(logs, entry) {
  const next = Array.isArray(logs) ? logs.slice() : [];
  next.push(entry);
  return next.slice(-50);
}

function errorMessage(item) {
  if (!item || typeof item !== 'object') return 'integration node failed';
  const err = item.error;
  if (typeof err === 'string' && err) return err;
  if (err && typeof err === 'object') {
    if (typeof err.message === 'string' && err.message) return err.message;
    if (typeof err.description === 'string' && err.description) return err.description;
  }
  if (typeof item.message === 'string' && item.message) return item.message;
  return 'integration node failed';
}

if (typeof $input === 'undefined') {
  return { appendLog: appendLog, errorMessage: errorMessage };
}

const item = $input.first().json || {};
const entry = {
  at: new Date().toISOString(),
  branch: 'integration',
  message: errorMessage(item),
};
const staticData = $getWorkflowStaticData('global');
staticData.logs = appendLog(staticData.logs, entry);
return [{
  json: {
    valid: 'yes',
    accepted: 'no',
    logged: 'yes',
    branch: 'integration',
    message: entry.message,
    httpStatus: 502,
  },
}];
